def tokeniser_sans_nombres(texte):
    return [m for m in tokeniser(texte) if not any(c.isdigit() for c in m)]

def tokeniser_jeton_nombre(texte):
    return ["<nombre>" if any(c.isdigit() for c in m) else m for m in tokeniser(texte)]

print(tokeniser_jeton_nombre("Call 09061701461 to claim your £1000 prize"))

